# Using Vicuna Language Model in SwiftUI

Here's a comprehensive guide to integrating Vicuna (or similar LLMs) into a SwiftUI app:

## Option 1: Using llama.cpp (Recommended for Local Usage)

### 1. Add llama.cpp Swift bindings

```swift
// Add to your Package.swift or use Swift Package Manager
// https://github.com/ggerganov/llama.cpp

dependencies: [
    .package(url: "https://github.com/ggerganov/llama.cpp", branch: "master")
]
```

### 2. Create a Model Manager

```swift
import Foundation

class VicunaManager: ObservableObject {
    @Published var response: String = ""
    @Published var isLoading: Bool = false

    private var modelPath: String

    init(modelPath: String) {
        self.modelPath = modelPath
    }

    func generate(prompt: String) async {
        await MainActor.run {
            isLoading = true
            response = ""
        }

        // Call your llama.cpp wrapper here
        let result = await processWithLlama(prompt: prompt)

        await MainActor.run {
            response = result
            isLoading = false
        }
    }

    private func processWithLlama(prompt: String) async -> String {
        // Implement llama.cpp integration
        return "Response from Vicuna"
    }
}
```

### 3. SwiftUI View

```swift
import SwiftUI

struct VicunaView: View {
    @StateObject private var vicunaManager: VicunaManager
    @State private var userInput: String = ""

    init() {
        let modelPath = Bundle.main.path(forResource: "vicuna-7b-q4", ofType: "gguf") ?? ""
        _vicunaManager = StateObject(wrappedValue: VicunaManager(modelPath: modelPath))
    }

    var body: some View {
        VStack {
            ScrollView {
                Text(vicunaManager.response)
                    .padding()
            }

            HStack {
                TextField("Enter prompt", text: $userInput)
                    .textFieldStyle(.roundedBorder)
                    .disabled(vicunaManager.isLoading)

                Button("Send") {
                    Task {
                        await vicunaManager.generate(prompt: userInput)
                        userInput = ""
                    }
                }
                .disabled(vicunaManager.isLoading || userInput.isEmpty)
            }
            .padding()

            if vicunaManager.isLoading {
                ProgressView()
            }
        }
    }
}
```

## Option 2: Using REST API (Cloud-based)

### 1. Create API Service

```swift
import Foundation

class VicunaAPIService: ObservableObject {
    @Published var response: String = ""
    @Published var isLoading: Bool = false

    private let apiURL = "YOUR_API_ENDPOINT"

    func sendPrompt(_ prompt: String) async throws {
        await MainActor.run { isLoading = true }

        var request = URLRequest(url: URL(string: apiURL)!)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")

        let body: [String: Any] = [
            "prompt": prompt,
            "max_tokens": 512,
            "temperature": 0.7
        ]
        request.httpBody = try JSONSerialization.data(withJSONObject: body)

        let (data, _) = try await URLSession.shared.data(for: request)
        let result = try JSONDecoder().decode(APIResponse.self, from: data)

        await MainActor.run {
            response = result.text
            isLoading = false
        }
    }
}

struct APIResponse: Codable {
    let text: String
}
```

### 2. SwiftUI Implementation

```swift
struct ContentView: View {
    @StateObject private var apiService = VicunaAPIService()
    @State private var input: String = ""
    @State private var messages: [Message] = []

    var body: some View {
        NavigationView {
            VStack {
                ScrollView {
                    ForEach(messages) { message in
                        MessageBubble(message: message)
                    }
                }

                InputBar(input: $input) {
                    sendMessage()
                }
            }
            .navigationTitle("Vicuna Chat")
        }
    }

    private func sendMessage() {
        let userMessage = Message(text: input, isUser: true)
        messages.append(userMessage)

        Task {
            do {
                try await apiService.sendPrompt(input)
                let aiMessage = Message(text: apiService.response, isUser: false)
                messages.append(aiMessage)
            } catch {
                print("Error: \(error)")
            }
        }
        input = ""
    }
}

struct Message: Identifiable {
    let id = UUID()
    let text: String
    let isUser: Bool
}

struct MessageBubble: View {
    let message: Message

    var body: some View {
        HStack {
            if message.isUser { Spacer() }
            Text(message.text)
                .padding()
                .background(message.isUser ? Color.blue : Color.gray.opacity(0.3))
                .foregroundColor(message.isUser ? .white : .primary)
                .cornerRadius(12)
            if !message.isUser { Spacer() }
        }
        .padding(.horizontal)
    }
}
```

## Option 3: Using MLC LLM for iOS

[MLC LLM](https://llm.mlc.ai/) provides native iOS support:

```bash
# Install via CocoaPods or SPM
pod 'MLCLLM'
```

## Important Considerations

1. **Model Size**: Vicuna models are large (7B-13B parameters). Consider using quantized versions (GGUF format)
2. **Memory**: Ensure device has sufficient RAM (8GB+ recommended)
3. **Performance**: Use Metal/GPU acceleration when possible
4. **Bundle Size**: Consider downloading models on-demand rather than bundling
5. **Privacy**: Local execution = better privacy, but requires more resources

